A = {1, 2}
B = {1, 2, 3}
print(A.issubset(B))          # True
print(A <= B)                 # True, same meaning as issubset
print(A < B)                  # True, proper subset since A != B

A = {1, 2, 3}
B = {3, 4, 5}
print(A | B)          # {1, 2, 3, 4, 5}
print(A.union(B))     # same result, method form

A = {1, 2, 3}
B = {3, 4, 5}
print(A & B)                 # {3}
print(A.intersection(B))     # same result, method form

